steps.eval:
(() => {
      const item = Array.from(document.querySelectorAll('.menu-item')).find(
        (node) => (node.textContent ?? '').trim() === 'О программе',
      );
      if (!item) throw new Error('нет пункта «О программе» в меню пользователя');
      item.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
      item.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
      return true;
    })()

steps.probe:
(() => {
  const rows = Array.from(document.querySelectorAll('.dialog-about .about-third-row')).map((row) => ({
    name: (row.querySelector('.about-third-name')?.textContent ?? '').trim(),
    license: (row.querySelector('.about-third-license')?.textContent ?? '').trim(),
  }));
  const hint = (document.querySelector('.dialog-about .about-third-hint')?.textContent ?? '').trim();
  const note = (document.querySelector('.dialog-about .about-third-note')?.textContent ?? '').trim();
  const themeNames = ['Blue Topaz', 'Catppuccin', 'RetroNotes', 'Wasp', 'Nordic'];
  const present = themeNames.filter((name) =>
    rows.some((r) => r.name === name || r.name === name + ' (неофициальная тема)'),
  );
  return {
    rows: rows.length,
    emptyLicenses: rows.filter((r) => r.license === '').length,
    themes: present.length,
    unofficial: rows.filter((r) => r.name.endsWith('(неофициальная тема)')).length,
    inter: rows.filter((r) => r.name === 'Inter' && r.license === 'OFL-1.1').length,
    jetbrains: rows.filter((r) => r.name === 'JetBrains Mono' && r.license === 'OFL-1.1').length,
    disclaimer: note.includes('ETN не связан с авторами тем'),
    hint: hint.includes('THIRD-PARTY-NOTICES'),
  };
})()
